class Solution {
public:
    string parseTernary(string expression) {
        stack<char> values;
        for (int i = static_cast<int>(expression.size()) - 1; i >= 0; --i) {
            char c = expression[i];
            if (c == '?') {
                continue;
            }
            if (c == ':') {
                continue;
            }
            if (i + 1 < static_cast<int>(expression.size()) && expression[i + 1] == '?') {
                char yes = values.top();
                values.pop();
                char no = values.top();
                values.pop();
                values.push(c == 'T' ? yes : no);
            } else {
                values.push(c);
            }
        }
        return string(1, values.top());
    }
};
